/** Starts the engine, waits for the stored state, optionally logs in, and runs what is due now. */
suspend fun TestScope.startRig(rig: TestRig, user: String? = null): TestRig {
    rig.host.start()
    rig.host.awaitReady()
    if (user != null) rig.host.login(user)
    runCurrent()
    return rig
}

/** Advances virtual time by [millis] and runs everything due at the new time. */
fun TestScope.advance(millis: Long) {
    advanceTimeBy(millis)
    runCurrent()
}

/** Advances in small steps until [condition] holds (tests wait on conditions, never on cycle counts). */
fun TestScope.advanceUntil(maxMillis: Long = 30_000L, condition: () -> Boolean) {
    var waited = 0L
    while (!condition()) {
        check(waited < maxMillis) { "condition not met within $maxMillis ms of virtual time" }
        advance(100L)
        waited += 100L
    }
}

